import {contactRows} from '/contacts.mjs';
const $=id=>document.getElementById(id);
const stages=['Researched','Reviewed','Contacted','Replied','Interested','Application started','Outcome'];
let records=[],selected=null;
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
async function api(path,data){const r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v;}
const fields={name:'Person or organisation',company:'Company',role:'Role',phone:'Business phone',email:'Business email',product:['Conversation','Loans or investments','Loans','Investments','Investment introductions'],contactKind:'Contact source quality',checkedAt:'Contact checked on',type:['Record type','partner','channel','prospect','insight'],area:'Location (explicitly stated)',segment:'Segment',source:'Source URL',evidence:'Supporting evidence',contact:'Published business contact route',relevance:'Why relevant',eligibility:'Known eligibility information (explicit evidence only)',unknowns:'Unknowns',next:'Next action',confidence:['Research confidence','Low','Medium','High'],priority:['Commercial priority','Unreviewed','Low','Medium','High'],status:['Stage',...stages],owner:'Owner',notes:'Notes',followUp:'Follow-up date',provenance:['Record origin','user-entered','live research','demonstration'],draft:'Outreach draft — edit before use'};
for(const [key,label] of Object.entries(fields)){const l=el('label',Array.isArray(label)?label[0]:label);let input;if(Array.isArray(label)){input=el('select');label.slice(1).forEach(v=>input.append(new Option(v,v)));}else if(['evidence','relevance','eligibility','unknowns','notes','draft'].includes(key)){input=el('textarea');input.rows=3;}else{input=el('input');input.type=key==='followUp'?'date':key==='source'?'url':'text';}input.id='f-'+key;input.maxLength=6000;l.append(input);$('fields').append(l);}
$('stage').append(new Option('All stages',''),...stages.map(s=>new Option(s,s)));
function render(){
 renderCalls();
 const people=contactRows(records);
 $('metrics').replaceChildren(...[['People to contact',people.filter(r=>!['Contacted','Replied','Interested','Application started','Outcome'].includes(r.status)).length],['Contacted',people.filter(r=>['Contacted','Replied','Interested','Application started','Outcome'].includes(r.status)).length],['Interested',people.filter(r=>['Interested','Application started'].includes(r.status)).length]].map(([label,count])=>{const d=el('div');d.append(el('span',label),el('strong',count));return d;}));
 const q=$('filter').value.toLowerCase();$('rows').replaceChildren();
 for(const r of records){if($('stage').value&&r.status!==$('stage').value||$('type-filter').value&&r.type!==$('type-filter').value||!JSON.stringify(r).toLowerCase().includes(q))continue;const row=el('tr'),name=el('td'),button=el('button',r.name);button.className='lead';button.onclick=()=>open(r);name.append(button,el('small',`${r.type} · ${r.area||'Location unknown'} · ${r.provenance}${r.suppressed?' · DO NOT CONTACT':''}`));row.append(name,el('td',r.status),el('td',`${r.confidence} / ${r.priority}`));$('rows').append(row);}
 if(!$('rows').children.length){const row=el('tr'),td=el('td','No records yet. Run research or add a public organisation manually.');td.colSpan=3;row.append(td);$('rows').append(row);}
}
async function refresh(){records=await api('/api/records');render();}
function open(r={}){selected=r.id?r:null;$('title').textContent=r.id?r.name:'New record';for(const key of Object.keys(fields))$('f-'+key).value=r[key]||({type:'partner',confidence:'Low',priority:'Unreviewed',status:'Researched',provenance:'user-entered'}[key]||'');$('suppressed').checked=!!r.suppressed;$('suppressed').disabled=!!r.suppressed;$('delete').hidden=!r.id;$('record-meta').textContent=r.discoveredAt?`Discovered ${r.discoveredAt} · Updated ${r.updatedAt}`:'';$('edit-error').textContent='';$('detail').showModal();}
$('add').onclick=()=>open();
$('edit').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(Object.keys(fields).map(k=>[k,$('f-'+k).value]));if(selected)data.id=selected.id;data.suppressed=$('suppressed').checked;try{await api('/api/records',data);await refresh();$('detail').close();}catch(e){$('edit-error').textContent=e.message;}};
$('delete').onclick=async()=>{if(!selected)return;if(!confirm('Delete this record? A do-not-contact identity will remain suppressed.'))return;try{await api('/api/delete',{id:selected.id});await refresh();$('detail').close();}catch(e){$('edit-error').textContent=e.message;}};
$('draft').onclick=()=>{if($('suppressed').checked){$('edit-error').textContent='This record is marked do not contact.';return;}const type=$('f-type').value;if(type==='insight'){$('edit-error').textContent='Market insights do not have outreach drafts.';return;}const name=$('f-name').value;const intros={prospect:'I am researching potential borrowing needs for a proposed Sycamore UK offering. Would you be willing to share your perspective in a short conversation?',channel:'Would your community be open to discussing whether a research conversation about borrowing needs would be useful to its audience?',partner:'Would you be open to an exploratory conversation about potential referral partnerships and the needs you see in your community?'};$('f-draft').value=`Hello ${name},\n\nI am researching a proposed UK loan offering for Sycamore. ${intros[type]}\n\nThe product terms and availability are still being clarified. This is an invitation to discuss needs, with no promise of lending or approval.\n\nIf this is not relevant, please let me know and I will record that you do not wish to be contacted.\n\n${$('f-owner').value||'[Your name]'}`;};
for(const id of ['filter','stage','type-filter'])$(id).addEventListener('input',render);
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const id of ['calls','pipeline','segments','terms'])$(id).hidden=id!==b.dataset.tab;};
const hypotheses=[
 ['Employed Nigerian professionals','Potential short-term cash-flow or cross-border commitments; demand untested.','Employment may align with supplied criteria; individual nationality, permits, income and guarantor availability remain unknown.','Public professional associations, alumni networks and opt-in interviews.','Guarantor availability, repayment costs, trust and alternative borrowing options.'],
 ['Recent arrivals with established employment','Possible relocation costs; needs interviews to establish demand.','Employment alone does not establish eligibility; required statement history and guarantor access may be barriers.','Public relocation events and professional networks inviting business enquiries.','Length of employment, documentation history and Nigerian guarantor requirement.'],
 ['Professional and alumni communities','Potential research and referral channels; members are not qualified borrowers.','Assess the organisation’s stated audience and contact permission, not individual eligibility.','Official association contact pages, newsletters and public events.','Administrator permission, audience relevance and whether a partnership is useful.']
];
$('segments').append(el('h2','Segment hypotheses'),el('p','These are starting hypotheses from the supplied brief. They are not evidence of demand or researched leads. Attach sources to pipeline insights to validate them.'));
for(const [name,need,fit,reach,barrier] of hypotheses){const card=el('article');card.className='board segment-card';card.append(el('h3',name),el('p','Potential need: '+need),el('p','Fit and unknowns: '+fit),el('p','Reach: '+reach),el('p','Barriers: '+barrier));const b=el('button','Research this segment');b.onclick=()=>{$('pipeline').hidden=false;$('segments').hidden=true;$('calls').hidden=true;$('question').value=`Research ${name} in Manchester for proposed Sycamore UK loan acquisition. Find public partner/channel sources, evidence, barriers and open questions. Do not infer individual eligibility.`;$('question').focus();};card.append(b);$('segments').append(card);}
const questions=[
 'Brand confirmed by the user: Sycamore.',
 'Rates: pasted requirements say “3.5% Pounds disbursement and 6% Naira disbursement”; January 2024 screenshots say 4% flat per month. Currency, charging period and current approved terms are unresolved.',
 'Amount and duration: historical screenshots show £100,000–£10,000,000 and 12 months maximum. Confirm currency, amounts and current availability; do not advertise these figures.',
 'Income documentation: later brief says three months; historical screenshots require six months of salary bank statements.',
 'Guarantor: later brief adds a car as collateral or three cheque leaves and address verification; screenshots specify a Nigeria-based guarantor without these details.',
 'Repayment: historical document specifies UK and Nigerian cards, Tranzfar Freedom subscription/account and Sprout. Later brief mentions UK card and GBP account. Confirm arrangements.',
 'Additional supplied requirements: recent utility bill, photo, BVN, Nigerian passport, work permit, employment letter, emails and UK address; later brief also mentions HMRC details. Keep these outside this research tool.',
 'Student eligibility and admission-letter requirement need clarification alongside employment/work-permit requirements.',
 'Both supplied versions mention 1% insurance. Confirm current basis and terms.',
 'Confirm legal entity, UK permissions, financial promotion process, privacy/contact basis, product availability and approved wording before customer-facing promotion.',
 '“Xa API”: provider and access capabilities are unidentified. No integration has been assumed.'
];
$('terms').append(el('h2','Missing product information'),el('p','Source comparison: user-pasted requirements and supplied Sales Department document dated 25 January 2024, version V.01. Neither is independently verified.'));const list=el('ul');questions.forEach(q=>list.append(el('li',q)));$('terms').append(list);
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>{const a=el('a');a.href='/api/export.csv';a.download='sycamore-pipeline.csv';a.click();};
$('brief').onclick=()=>download('sycamore-research-brief.md',`# Sycamore UK research brief\nGenerated ${new Date().toISOString()}\n\n## Segment hypotheses\n${hypotheses.map(h=>'### '+h[0]+'\n'+h.slice(1).join('\n')).join('\n\n')}\n\n## Pipeline evidence\n${records.map(r=>`### ${r.name}\nType: ${r.type}; origin: ${r.provenance}; stage: ${r.status}; suppressed: ${r.suppressed}\nSource: ${r.source||'Not supplied'}\nDiscovered: ${r.discoveredAt}\nEvidence: ${r.evidence}\nRelevance: ${r.relevance}\nUnknowns: ${r.unknowns}\nNext action: ${r.next}\nConfidence: ${r.confidence}; priority: ${r.priority}`).join('\n\n')||'No records saved.'}\n\n## Unresolved product questions\n${questions.map(q=>'- '+q).join('\n')}`,'text/markdown');
$('ask').onsubmit=async e=>{e.preventDefault();$('run').disabled=true;const p=el('article');p.append(el('h3',$('question').value),el('p','Researching up to five public sources…'));$('history').prepend(p);try{const result=await api('/api/research',{question:$('question').value,provider:$('provider').value,search:true,rows:records.slice(0,35)});p.replaceChildren(el('h3',`Research · ${result.discoveredAt}${result.cached?' · cached':''}`),el('p',result.reply),el('p',`Provider: ${result.provider||'direct'} · Cost: ${result.costUsd==null?'not reported':'$'+result.costUsd.toFixed(3)}${result.partial?' · partial run':''}`));for(const source of result.search||[]){const card=el('div'),a=el('a',source.title);if(/^https?:\/\//i.test(source.url))a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';const b=el('button','Review & save');b.onclick=()=>open({name:source.title,source:source.url,evidence:source.excerpt||'',notes:source.verification,provenance:'live research',unknowns:'Audience, contact permission, relevance and all eligibility information require review.'});card.append(a,el('p',source.verification),b);p.append(card);}}catch(e){p.append(el('p',e.message+' Manual entry remains available.'));}finally{$('run').disabled=false;}};
$('settings').onclick=()=>$('connections').showModal();$('connect').onsubmit=async e=>{e.preventDefault();try{await api('/api/firecrawl',{key:$('key').value});$('key').value='';$('connection-note').textContent='Connection saved for this server session.';}catch(e){$('connection-note').textContent=e.message;}};
refresh().catch(e=>$('notice').textContent='Could not load stored records: '+e.message);

api('/api/saved-research').then(result=>{if(!result)return;const p=el('article');p.append(el('h3','Saved connector research · '+result.discoveredAt),el('p',result.reply),el('p',result.provider+' · $'+result.costUsd.toFixed(3)));for(const source of result.search){const a=el('a',source.title);a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';const b=el('button','Review & save');b.onclick=()=>open({name:source.title,source:source.url,evidence:source.excerpt,notes:source.verification,provenance:'live research'});p.append(a,el('p',source.verification),b);} $('history').append(p);}).catch(()=>{});

function renderCalls(){
 const rows=contactRows(records,{query:$('call-search').value,product:$('call-product').value});
 const all=contactRows(records);
 $('call-count').textContent=`${all.length} people · ${all.filter(r=>r.phone).length} phone numbers · ${all.filter(r=>r.email).length} business emails`;
 const body=$('call-rows');body.replaceChildren();
 for(const r of rows){
  const tr=el('tr'),person=el('td'),name=el('button',r.name);name.className='lead';name.onclick=()=>open(r);person.append(name,el('small',r.role+' · '+r.company));
  const contact=el('td');if(r.phone){const a=el('a',r.phone);a.href='tel:'+r.phone.replace(/[^+0-9]/g,'');contact.append(a,el('br'));}if(r.email){const a=el('a',r.email);if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email))a.href='mailto:'+r.email;contact.append(a);}contact.append(el('small',r.contactKind));
  const pitch=el('td');pitch.append(el('strong',r.product||'Loans or investments'),el('p',r.relevance));const details=el('details'),summary=el('summary','What to say');details.append(summary,el('p',r.draft));pitch.append(details);const source=el('a','Contact source ↗');if(/^https?:\/\//.test(r.source))source.href=r.source;source.target='_blank';source.rel='noopener noreferrer';pitch.append(source,el('small','Checked '+r.checkedAt));
  const action=el('td');const stage=el('select');stage.setAttribute('aria-label','Status for '+r.name);stages.forEach(value=>stage.append(new Option(value,value)));stage.value=r.status;stage.onchange=async()=>{stage.disabled=true;try{await api('/api/records',{...r,status:stage.value});await refresh();}catch(e){$('notice').textContent=e.message;stage.value=r.status;}finally{stage.disabled=false;}};action.append(stage);const b=el('button','Notes & follow-up');b.onclick=()=>open(r);action.append(b);tr.append(person,contact,pitch,action);body.append(tr);
 }
 if(!rows.length){const tr=el('tr'),td=el('td','No matching people.');td.colSpan=4;tr.append(td);body.append(tr);}
}
for(const id of ['call-search','call-product'])$(id).addEventListener('input',renderCalls);
$('call-export').onclick=()=>$('export').click();
